const item = $input.first();

const headersOriginais = item.json.headers ?? {};

// Padroniza os nomes dos headers para minúsculas
const headers = Object.fromEntries(
  Object.entries(headersOriginais).map(([chave, valor]) => [
    chave.toLowerCase(),
    valor,
  ])
);

function texto(valor) {
  return String(valor ?? '').trim();
}

function decodificar(valor) {
  const valorTexto = texto(valor);

  if (!valorTexto) {
    return '';
  }

  try {
    return decodeURIComponent(valorTexto);
  } catch {
    return valorTexto;
  }
}

const pdfRecebido = Boolean(item.binary?.data);

const nomeArquivo =
  decodificar(headers['x-file-name']) ||
  texto(item.binary?.data?.fileName) ||
  'orcamento-sem-nome.pdf';

const sharePointItemId = texto(
  headers['x-sharepoint-item-id']
);

const sharePointIdentifier = decodificar(
  headers['x-sharepoint-identifier']
);

const caminhoArquivo = decodificar(
  headers['x-sharepoint-path']
);

const origemArquivo =
  texto(headers['x-source']) ||
  'SHAREPOINT';

/*
 * ID genérico para controle de duplicidade.
 *
 * Para arquivos do SharePoint:
 * SHAREPOINT:123
 */
const arquivoId = sharePointItemId
  ? `SHAREPOINT:${sharePointItemId}`
  : sharePointIdentifier
    ? `SHAREPOINT:${sharePointIdentifier}`
    : '';

if (pdfRecebido) {
  item.binary.data.fileName = nomeArquivo;

  item.binary.data.mimeType =
    item.binary.data.mimeType ||
    headers['content-type'] ||
    'application/pdf';
}

return [
  {
    json: {
      ...item.json,

      Origem_Arquivo: origemArquivo,
      Arquivo_ID: arquivoId,

      SharePoint_Item_ID: sharePointItemId,
      SharePoint_Identifier: sharePointIdentifier,
      Caminho_Arquivo: caminhoArquivo,

      Nome_Arquivo: nomeArquivo,
      MimeType:
        item.binary?.data?.mimeType ||
        headers['content-type'] ||
        'application/pdf',

      PDF_Recebido: pdfRecebido,

      Status_Entrada: pdfRecebido
        ? 'RECEBIDO'
        : 'ERRO_RECEBIMENTO',

      Data_Recebimento: new Date().toISOString(),
    },

    binary: item.binary,
  },
];

