const item = $input.first();
const json = item.json ?? {};

const statusPermitidos = [
  'PROCESSADO',
  'ERRO_LEITURA',
  'ERRO_TECNICO',
  'IGNORADO_DUPLICADO',
];

const statusRecebido = String(
  json.status ||
  json.Status_Processamento ||
  ''
).trim().toUpperCase();

const status = statusPermitidos.includes(statusRecebido)
  ? statusRecebido
  : 'ERRO_TECNICO';

return [
  {
    json: {
      sucesso: status === 'PROCESSADO',

      status,

      codigoOrcamento:
        json.codigoOrcamento ||
        json.Codigo_Orcamento ||
        '',

      arquivoId:
        json.Arquivo_ID ||
        '',

      nomeArquivo:
        json.Nome_Arquivo ||
        '',

      mensagem:
        json.mensagem ||
        json.Erro ||
        (
          status === 'PROCESSADO'
            ? 'Orçamento processado com sucesso.'
            : 'O processamento não foi concluído.'
        ),
    },
  },
];
